package dev.jobflow.api;
import com.fasterxml.jackson.databind.JsonNode; import dev.jobflow.domain.*; import jakarta.validation.constraints.*; import java.time.Instant; import java.util.UUID;
public final class JobDtos { private JobDtos(){} public record CreateJobRequest(@NotNull JobType type,@NotNull JsonNode payload,JobPriority priority,@Min(1) @Max(20) Integer maxAttempts){} public record JobResponse(UUID id,JobType type,JobPriority priority,JobStatus status,Instant availableAt,int attemptCount,int maxAttempts,JsonNode result,String errorCode,String errorMessage,Instant createdAt,Instant updatedAt){ public static JobResponse of(Job j){return new JobResponse(j.getId(),j.getType(),j.getPriority(),j.getStatus(),j.getAvailableAt(),j.getAttemptCount(),j.getMaxAttempts(),j.getResult(),j.getErrorCode(),j.getErrorMessage(),j.getCreatedAt(),j.getUpdatedAt());}} }
